import{z as B,x as p,o as E,c as d,q as o,j as s,D as t,d as r,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"KMP 串匹配","description":"","frontmatter":{"title":"KMP 串匹配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kmp.md","filePath":"cs/kmp.md","lastUpdated":1791413859000}'),A={name:"cs/kmp.md"};function m(P,a,D,h,C,c){const i=p("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="kmp-串匹配" tabindex="-1">KMP 串匹配 <a class="header-anchor" href="#kmp-串匹配" aria-label="Permalink to &quot;KMP 串匹配&quot;">​</a></h1><div class="epigraph"><p>模式在失配处已经对齐过的前缀信息，足够决定下一步滑到哪，而不把文本指针回退。</p><footer>—— 据 Knuth, Morris and Pratt, Fast Pattern Matching in Strings, 1977；CLRS 第 32 章整理</footer></div><p>上一课<a href="/cs/bipartite-match">二分图匹配</a>收束了图上的组合优化主干。串是另一类对象：文本 \\(T\\)、模式 \\(P\\)，问 \\(P\\) 是否作为连续片段出现。本课不把串当图的路径。缺口是：朴素匹配最坏 \\(\\Theta(nm)\\)，每次失配把 \\(T\\) 的指针往回退。KMP 预计算 \\(P\\) 的前缀函数，扫描 \\(T\\) 只前进。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素：每个起点 \\(s\\) 比较 \\(P\\) 与 \\(T[s..]\\)。最坏如 \\(aaa\\ldots b\\) 对 \\(aa\\ldots ab\\)。缺口不是哈希（那是期望），而是<strong>确定性线性</strong>：预处理 \\(P\\) 得 \\(\\pi\\)，使 \\(\\pi[q]\\) 为真前缀 \\(P[1..q]\\) 的最长真后缀长度且该后缀也是前缀。匹配时失配跳到 \\(\\pi[q]\\)， \\(T\\) 的下标不减。</p><p>总时间 \\(\\Theta(n+m)\\)。仍在 P，比较模型换成字符相等。</p><h3 id="前缀函数不是失败时的「往左数一格」" tabindex="-1">前缀函数不是失败时的「往左数一格」 <a class="header-anchor" href="#前缀函数不是失败时的「往左数一格」" aria-label="Permalink to &quot;前缀函数不是失败时的「往左数一格」&quot;">​</a></h3><p>\\(\\pi\\) 来自 \\(P\\) 自己的周期。错用 \\(\\pi[q]-1\\) 或固定滑 \\(1\\) 会漏匹配或退回平方。\\(\\pi\\) 的计算本身是对 \\(P\\) 的「自匹配」，同一套转移。</p><p><span class="marginnote">Knuth–Morris–Pratt 1977 把 Morris–Pratt 的思想写成线性最坏。Boyer–Moore 从右扫，本课不并行展开。后课词法用正则，那是语言而非单模式精确匹配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先算 \\(\\pi[1..m]\\)：\\(q\\) 从 \\(0\\) 扫 \\(P\\)，失配时 \\(q\\leftarrow\\pi[q]\\)。再扫 \\(T\\)：同样转移，当 \\(q=m\\) 报告一次出现，\\(q\\leftarrow\\pi[m]\\) 找下一个。</p>',11)),(E(),s(l,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A8%A1%E5%BC%8F%20P%22%5D%20--%3E%20PI%5B%22%E5%89%8D%E7%BC%80%E5%87%BD%E6%95%B0%20%CF%80%22%5D%0A%20%20PI%20--%3E%20SCAN%5B%22%E6%89%AB%E6%96%87%E6%9C%AC%20T%EF%BC%8C%E5%A4%B1%E9%85%8D%E6%8C%89%20%CF%80%20%E8%B7%B3%22%5D%0A%20%20SCAN%20--%3E%20HIT%5B%22%E6%8A%A5%E5%91%8A%E5%87%BA%E7%8E%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"字符表大小不进渐近的主导项；比较是相等测试。多模式要用 Aho–Corasick，本课单模式。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[r("文本指针单调，故 \\(O(n)\\) 次转移；\\(\\pi\\) 的摊还同样：\\(q\\) 的增减有势函数。与"),e("a",{href:"/cs/amortized-analysis"},"摊还分析"),r("同类记账，本课不重写势能定义。")],-1)),a[6]||(a[6]=e("p",null,"第一张图是整个流程；这张放大失配那一刻，回答「为什么跳到 \\(\\pi[q]\\) 就不会漏」：已匹配的那段同时是 \\(P\\) 的前缀，它的最长 border 让新模式位置与文本已读部分重新咬合，而 \\(T\\) 的指针一步都没退。",-1)),(E(),s(l,null,{default:t(()=>[n(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20MM%5B%22T%5Bi%5D%20%E4%B8%8E%20P%5Bq%2B1%5D%20%E5%A4%B1%E9%85%8D%22%5D%20--%3E%20KNOWN%5B%22%E5%B7%B2%E5%8C%B9%E9%85%8D%E6%AE%B5%20P%5B1..q%5D%20%E4%BF%A1%E6%81%AF%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20KNOWN%20--%3E%20BORDER%7B%22%E8%AF%A5%E6%AE%B5%E7%9A%84%E6%9C%80%E9%95%BF%20border%3Cbr%2F%3E%E9%95%BF%E5%BA%A6%E6%98%AF%E5%A4%9A%E5%B0%91%EF%BC%9F%22%7D%0A%20%20BORDER%20--%3E%7C%22%CF%80%5Bq%5D%20%3D%20%E5%89%8D%E7%BC%80%E5%85%BC%E5%90%8E%E7%BC%80%E7%9A%84%E9%87%8D%E5%90%88%E9%95%BF%E5%BA%A6%22%7C%20SHIFT%5B%22%E6%A8%A1%E5%BC%8F%E6%BB%91%E5%88%B0%20border%20%E5%AF%B9%E9%BD%90%E6%96%87%E6%9C%AC%E5%B0%BE%E9%83%A8%22%5D%0A%20%20SHIFT%20--%3E%20RESUME%5B%22%E7%BB%A7%E7%BB%AD%E5%9C%A8%E5%90%8C%E4%B8%80%E4%B8%AA%20T%5Bi%5D%20%E4%B8%8A%E6%AF%94%E8%BE%83%22%5D%0A%20%20BORDER%20--%3E%7C%22%CF%80%5Bq%5D%20%3D%200%22%7C%20ZERO%5B%22%E6%A8%A1%E5%BC%8F%E5%AF%B9%E9%BD%90%E5%88%B0%20T%5Bi%5D%20%E9%87%8D%E6%96%B0%E4%BB%8E%20P%5B1%5D%20%E6%AF%94%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>哈希匹配（Rabin–Karp）期望线性、最坏平方，模型不同。本课要最坏线性。</p><p><span class="marginnote">数字实例：模式 \\(P=\\) <code>ababaca</code> 的前缀函数是 \\(\\pi=[0,0,1,2,3,0,1]\\)。比如 \\(\\pi[5]=3\\)：<code>ababa</code> 的前三个字符 <code>aba</code> 同时也是它的最后三个字符。失配在 \\(q=5\\) 时直接把模式滑到让 <code>aba</code> 对齐已比较的尾部，省掉三次明知必败的比较。</span></p><p><span class="marginnote">直觉类比：失配跳转像考试对答案——你已经确认过的部分（已匹配前缀）不用从头再验，直接用「它自己开头和结尾有多重合」这张表接着往下判。朴素算法错在哪：每失配一次就把卷子翻回第一题重做。</span></p><p><span class="marginnote">常见误区：初学者容易把跳转写成 \\(\\pi[q]-1\\) 或「固定往右滑一格」。对 <code>aaaa</code> 这类强周期模式，滑一格会让比较次数回到平方级；正确跳转的依据是 border 结构，不是相邻位置——差一个下标，渐近就差一个量级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做正则、不写近似匹配、不处理通配符。二维匹配、后缀数组是另一课序，不插入。流式只需 \\(\\pi\\) 与当前 \\(q\\)，不必存整份 \\(T\\) 的回退。</p><p>后课默认：单模式精确匹配最坏 \\(\\Theta(n+m)\\) 用 KMP。贪心作为设计法的正确性论证是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀函数把失配变成模式内部的跳转，\\(T\\) 指针不回退。</li><li>预处理加扫描 \\(\\Theta(n+m)\\)。</li><li>单模式；正则与多模式不是本课。</li><li>出处：Knuth, Morris and Pratt, 1977；CLRS 第 32 章。</li></ul>',9))])}const q=B(A,[["render",m]]);export{b as __pageData,q as default};
